FROM
(select id, unique_id, name, sex, phone, card_no, account, email, dept_id, datasource, flag, status as tstatus, effective_begin_time, effective_end_time,  remark, create_by, update_by, create_time, update_time, batch_date, tenant_id, ext_attrs ,
(CASE WHEN NOW() >= effective_begin_time AND NOW() <= effective_end_time THEN 0 ELSE 2 END) as tstate
from base_person_info info

